verus! {

    /// Given a non‐empty slice of i32, returns an integer that is
    /// less than or equal to every element of the slice (i.e. the minimum).
    fn min_array(a: &[i32]) -> (r: i32)
        requires
            a.len() > 0,
        ensures
            // r is ≤ every element in the array
            forall |i: usize|  i < a.len() ==> r <= a[i],
        ensures
            // r actually appears in the array
            exists |j: usize|  j < a.len() && r == a[j]
    {
        // We track the index of the current minimum so we can show an existence.
        let mut min_idx: usize = 0;
        let mut i: usize = 1;
        let mut current_min: i32 = a[0];
        // Loop over the rest of the slice
        while i < a.len()
            invariant
                // bounds
                i <= a.len(),
                min_idx < i,
                // current_min is always a[min_idx]
                current_min == a[min_idx],
                // current_min is ≤ all elements seen so far
                forall |k: usize| k < i ==> current_min <= a[k],
            decreases
                a.len() - i
        {
            if a[i] < current_min {
                current_min = a[i];
                min_idx = i;
            }
            i += 1;
        }
        // After the loop, i == a.len(), so current_min ≤ all elements in a
        assert forall |k: usize| k < a.len() ==> current_min <= a[k];
        // And current_min == a[min_idx] with min_idx < a.len(), giving existence
        assert current_min == a[min_idx];
        return current_min;
    }

}